fn a_byte(n: i32) -> u8 {
    n as u8
}

fn promedio(v: &[u8]) -> f64 {
    let s: u8 = v.iter().sum();
    s as f64 / v.len() as f64
}

fn suma(arr: &[i32]) -> i32 {
    let mut total = 0;
    for i in 0..arr.len() - 1 {
        total += arr[i];
    }
    total
}

fn es_impar(n: i32) -> bool {
